USE empresa;
/* 8 */ SELECT NUM_EMPLEADO FROM empleados WHERE COMISION > SALARIO / 2;
/* 9 */ SELECT NUM_EMPLEADO FROM empleados WHERE COMISION <= SALARIO * 0.25;
/* 10 */ SELECT CONCAT('Nombre ', NOMBRE_EMPLEADO, ' Puesto ', PUESTO) AS empleado FROM empleados;
/* 11 */ SELECT SALARIO, COMISION FROM empleados WHERE NUM_EMPLEADO > 7500;
/* 12 */ SELECT NOMBRE_EMPLEADO, PUESTO FROM empleados WHERE NOMBRE_EMPLEADO LIKE 'J%' ORDER BY NOMBRE_EMPLEADO, PUESTO;
/* 13 */ SELECT NUM_EMPLEADO, SALARIO, COMISION, SALARIO + COMISION AS salario_total FROM empleados WHERE COMISION IS NOT NULL ORDER BY NUM_EMPLEADO;
/* 14 */ SELECT NUM_EMPLEADO, SALARIO, COMISION, SALARIO AS salario_total FROM empleados WHERE COMISION IS NULL ORDER BY NUM_EMPLEADO;
/* 15 */ SELECT NUM_EMPLEADO, SALARIO, COMISION, SALARIO + COMISION AS salario_total FROM empleados WHERE COMISION IS NOT NULL UNION ALL SELECT NUM_EMPLEADO, SALARIO, COMISION, SALARIO AS salario_total FROM empleados WHERE COMISION IS NULL ORDER BY NUM_EMPLEADO;
/* 16 */ SELECT NUM_EMPLEADO, SALARIO, COMISION, IF(COMISION IS NULL, SALARIO, SALARIO + COMISION) AS salario_total FROM empleados ORDER BY NUM_EMPLEADO;
/* 17 */ SELECT NOMBRE_EMPLEADO FROM empleados WHERE SALARIO > 1000 AND NUM_JEFE = 7698;
/* 18 */ SELECT NOMBRE_EMPLEADO FROM empleados WHERE SALARIO <= 1000 OR NUM_JEFE <> 7698 OR NUM_JEFE IS NULL;
/* 19 */ SELECT NOMBRE_EMPLEADO, (COALESCE(COMISION,0) / (SALARIO + COALESCE(COMISION,0))) * 100 AS porcentaje FROM empleados ORDER BY NOMBRE_EMPLEADO;
/* 20 */ SELECT NUM_EMPLEADO FROM empleados WHERE NUM_DEPARTAMENTO = 10 AND NOMBRE_EMPLEADO NOT LIKE '%LA%';
/* 21 */ SELECT NUM_EMPLEADO FROM empleados WHERE NUM_JEFE IS NULL;
/* 22 */ SELECT NOMBRE_EMPLEADO, NUM_DEPARTAMENTO FROM empleados WHERE PUESTO='ADMINISTRATIVO' AND NUM_DEPARTAMENTO <> 10 AND SALARIO > 800 ORDER BY FECHA_ALTA;
/* 23 */ SELECT * FROM empleados WHERE CHAR_LENGTH(NOMBRE_EMPLEADO)=5;
/* 24 */ SELECT * FROM empleados WHERE CHAR_LENGTH(NOMBRE_EMPLEADO)>=5;
/* 25 */ SELECT * FROM empleados WHERE (NOMBRE_EMPLEADO LIKE 'A%' AND SALARIO > 1000) OR (COMISION IS NOT NULL AND COMISION > 0 AND NUM_DEPARTAMENTO=30);
/* 26 */ SELECT NOMBRE_EMPLEADO, SALARIO + COMISION AS salario_total FROM empleados WHERE COMISION IS NOT NULL ORDER BY salario_total;
/* 27 */ SELECT NOMBRE_EMPLEADO, SALARIO AS salario_actual, SALARIO*1.06 AS salario_futuro, IF(COMISION IS NULL,'NO','SÍ') AS tiene_comision FROM empleados;
/* 28 */ SELECT * FROM empleados WHERE NUM_EMPLEADO IN (7844,7900,7521,7782,7934,7678,7369);
/* 29 */ SELECT NUM_EMPLEADO FROM empleados WHERE NUM_JEFE > NUM_EMPLEADO AND ((SALARIO > 1000 AND SALARIO < 2000) OR NUM_DEPARTAMENTO=30);
/* 30 */ SELECT MAX(SALARIO) AS salario_maximo, SUM(COALESCE(COMISION,0)) AS total_comisiones, COUNT(*) AS numero_empleados FROM empleados;
/* 31 */ SELECT NOMBRE_EMPLEADO, PUESTO, SALARIO FROM empleados WHERE SALARIO >= (SELECT MAX(SALARIO) FROM empleados WHERE NOMBRE_EMPLEADO='ALLEN');
/* 32 */ SELECT NOMBRE_EMPLEADO FROM empleados ORDER BY NOMBRE_EMPLEADO DESC LIMIT 1;
/* 33 */ SELECT MAX(SALARIO) AS mayor_salario, MIN(SALARIO) AS menor_salario, MAX(SALARIO)-MIN(SALARIO) AS diferencia FROM empleados;
/* 34 */ SELECT NUM_EMPLEADO, NOMBRE_EMPLEADO, SALARIO FROM empleados WHERE SALARIO=(SELECT MAX(SALARIO) FROM empleados) OR SALARIO=(SELECT MIN(SALARIO) FROM empleados);
/* 35 */ SELECT NUM_DEPARTAMENTO, AVG(SALARIO) AS media FROM empleados WHERE SALARIO < 5000 GROUP BY NUM_DEPARTAMENTO HAVING AVG(SALARIO) > 900;
/* 36 */ SELECT NUM_EMPLEADO FROM empleados WHERE SALARIO >= (SELECT AVG(SALARIO) FROM empleados);
/* 37 */ SELECT e.* FROM empleados e WHERE e.SALARIO > ALL (SELECT e2.SALARIO FROM empleados e2 WHERE e2.NUM_DEPARTAMENTO=e.NUM_DEPARTAMENTO AND e2.NUM_EMPLEADO<>e.NUM_EMPLEADO);
/* 38 */ SELECT COUNT(*) AS empleados_con_comision FROM empleados WHERE COMISION IS NOT NULL;
/* 39 */ SELECT NUM_DEPARTAMENTO, COUNT(*) AS numero_empleados FROM empleados GROUP BY NUM_DEPARTAMENTO HAVING COUNT(*)>3;
/* 40 */ SELECT e.NUM_EMPLEADO, e.NOMBRE_EMPLEADO, e.PUESTO FROM empleados e WHERE e.NUM_DEPARTAMENTO=10 AND e.PUESTO IN (SELECT ev.PUESTO FROM empleados ev JOIN departamentos d ON d.NUM_DEPARTAMENTO=ev.NUM_DEPARTAMENTO WHERE d.NOMBRE='VENTAS');
/* 41 */ SELECT d.* FROM departamentos d WHERE NOT EXISTS (SELECT 1 FROM empleados e WHERE e.NUM_DEPARTAMENTO=d.NUM_DEPARTAMENTO);
/* 42 */ SELECT e.* FROM empleados e JOIN departamentos d ON d.NUM_DEPARTAMENTO=e.NUM_DEPARTAMENTO WHERE d.LOCALIDAD IN ('DALLAS','NEW YORK');
/* 43 */ SELECT NUM_DEPARTAMENTO AS departamento, SUM(SALARIO) AS suma FROM empleados GROUP BY NUM_DEPARTAMENTO ORDER BY suma DESC LIMIT 1;
